-- Gerado por scripts/insert_natal_deco.mjs — "Árvore de Natal com Nomes" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('arvore_nomes', 'Árvore de Natal com Nomes', 'Árvore de Natal plana com os nomes da família em relevo (um em cada ramo) e uma estrela, de pé numa base com duas velas LED à frente.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['árvore', 'nomes', 'família', 'personalizado', 'LED', 'natal'], 1, $tpl$// Árvore de Natal com Nomes — o modelo está em templates/decoracao/partes/arvore_nomes.scad (backend)
include </app/templates/decoracao/arvore_nomes.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"arvore_nomes","ui":{"widget":"hidden"}},"nome1":{"order":1,"default":"Maria","ui":{"label":"Nome no ramo de baixo","widget":"text","maxLength":16}},"nome2":{"order":2,"default":"João","ui":{"label":"Nome no 2.º ramo","widget":"text","maxLength":14}},"nome3":{"order":3,"default":"Ana","ui":{"label":"Nome no 3.º ramo","widget":"text","maxLength":12}},"nome4":{"order":4,"default":"Rui","ui":{"label":"Nome no ramo de cima","widget":"text","maxLength":8}},"fonte":{"order":5,"default":"Luckiest Guy","ui":{"label":"Tipo de letra","widget":"select","options":["Luckiest Guy","Chewy","Baloo 2","Sigmar One","Pacifico","Lobster","Open Sans"]}},"largura":{"order":6,"type":"number","min":80,"max":240,"unit":"mm","default":140,"ui":{"label":"Largura da árvore","widget":"slider","step":1}},"espessura":{"order":7,"type":"number","min":2.4,"max":8,"unit":"mm","default":4,"ui":{"label":"Espessura da árvore","widget":"slider","step":0.2}},"diametro_vela":{"order":8,"type":"number","min":30,"max":60,"unit":"mm","default":39.5,"ui":{"label":"Diâmetro das cavidades das velas","widget":"slider","step":0.5}},"pecas":{"order":9,"default":"Árvore e base","ui":{"label":"Peças","widget":"select","options":["Árvore e base","Só a árvore","Só a base"]}},"info_arvore":{"order":99,"default":null,"ui":{"widget":"info","text":"🎄 Os nomes encolhem sozinhos para caber no ramo (deixa um vazio para não ter nome). A árvore e a base imprimem-se deitadas, sem suportes; a árvore encaixa de pé na ranhura da base. Dica: troca de cor na camada onde começam os nomes (verde → dourado). Recomendamos velas LED (as cavidades são para velas de chá LED, 38 × 16 mm, com folga). Nunca uses velas a sério: o plástico amolece e arde."}}},"ajuste_texto":{"campos":["nome1","nome2","nome3","nome4"],"largura_util":59.4,"largura_por_campo":{"nome1":59.4,"nome2":47,"nome3":34.4,"nome4":17.9},"tamanho_por_campo":{"nome1":10.5,"nome2":10,"nome3":9.5,"nome4":9}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
